fn xmlRegStateAddTrans(
    mut ctxt: xmlRegParserCtxtPtr,
    mut state: xmlRegStatePtr,
    mut atom: xmlRegAtomPtr,
    mut target: xmlRegStatePtr,
    mut counter: c_int,
    mut count: c_int,
) {
    unsafe {
        // SAFETY: All raw pointer dereferences below follow the original function's preconditions:
        // `ctxt` is assumed valid by callers; `state` and `target` are checked for null before dereference;
        // `state.trans` is only dereferenced within the allocated `nbTrans`/`maxTrans` bounds maintained here.
        if state.is_null() {
            (*ctxt).error = XML_REGEXP_COMPILE_ERROR as c_int;
            xmlRegexpErrCompile(
                ctxt,
                b"add state: state is NULL\0" as *const u8 as *const c_char,
            );
            return;
        }
        if target.is_null() {
            (*ctxt).error = XML_REGEXP_COMPILE_ERROR as c_int;
            xmlRegexpErrCompile(
                ctxt,
                b"add state: target is NULL\0" as *const u8 as *const c_char,
            );
            return;
        }

        let state_ref = &mut *state;
        let target_no = (*target).no;

        let mut nrtrans = state_ref.nbTrans - 1;
        let trans_base = state_ref.trans;
        while nrtrans >= 0 {
            let trans = trans_base.offset(nrtrans as isize);
            if (*trans).atom == atom
                && (*trans).to == target_no
                && (*trans).counter == counter
                && (*trans).count == count
            {
                return;
            }
            nrtrans -= 1;
        }

        if state_ref.maxTrans == 0 {
            state_ref.maxTrans = 8;
            state_ref.trans = xmlMalloc.expect("non-null function pointer")(
                (state_ref.maxTrans as size_t)
                    .wrapping_mul(::core::mem::size_of::<xmlRegTrans>() as size_t),
            ) as *mut xmlRegTrans;
            if state_ref.trans.is_null() {
                xmlRegexpErrMemory(
                    ctxt,
                    b"adding transition\0" as *const u8 as *const c_char,
                );
                state_ref.maxTrans = 0;
                return;
            }
        } else if state_ref.nbTrans >= state_ref.maxTrans {
            let old_max = state_ref.maxTrans;
            state_ref.maxTrans = old_max * 2;
            let tmp = xmlRealloc.expect("non-null function pointer")(
                state_ref.trans as *mut c_void,
                (state_ref.maxTrans as size_t)
                    .wrapping_mul(::core::mem::size_of::<xmlRegTrans>() as size_t),
            ) as *mut xmlRegTrans;
            if tmp.is_null() {
                xmlRegexpErrMemory(
                    ctxt,
                    b"adding transition\0" as *const u8 as *const c_char,
                );
                state_ref.maxTrans = old_max;
                return;
            }
            state_ref.trans = tmp;
        }

        let idx = state_ref.nbTrans as isize;
        let trans = state_ref.trans.offset(idx);
        (*trans).atom = atom;
        (*trans).to = target_no;
        (*trans).counter = counter;
        (*trans).count = count;
        (*trans).nd = 0;
        state_ref.nbTrans += 1;

        xmlRegStateAddTransTo(ctxt, target, state_ref.no);
    }
}

